  FT["SG-H1141"] = {"id":"SG-H1141","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/DIA2005-RG1?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"存款保险（罪行构成）条例","en":"Deposit Insurance (Composition of Offences) Regulations","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation DIA2005-RG1","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1141-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Regulations may be cited as the Deposit Insurance (Composition of Offences) Regulations."}},{"id":"SG-H1141-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Compoundable offences"},"text":{"en":"2. The following offences may be compounded by the Authority in accordance with section 46(1) of the Act:\n(a)an offence under the Act which is punishable with a fine only;\n(b)an offence under section 29, 41(1)(b) or 42 of the Act; and\n(c)an offence under subsection (1)(a) of section 41 of the Act, where the non-compliance referred to in that subsection constitutes a compoundable offence under paragraph (a) or (b).\n[G.N. No. S 7/2006]"}}],"pack":"sg-p14","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Deposit Insurance (Composition of Offences) Regulations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
